import XCTest

final class BskyTests: XCTestCase {
    let outDir = "/private/var/folders/vl/g_dyzwvs4_52rz0rdks_3j900000gp/T/opencode"

    func testOpenProfile() throws {
        let app = XCUIApplication(bundleIdentifier: "xyz.blueskyweb.app")
        app.activate()
        sleep(2)
        let author = app.staticTexts["whiskers"].firstMatch
        XCTAssertTrue(author.waitForExistence(timeout: 15), "author label not found")
        author.tap()
        sleep(3)
        try? app.debugDescription.write(toFile: outDir + "/tree_profile.txt", atomically: true, encoding: .utf8)
        let shot = XCUIScreen.main.screenshot()
        try? shot.pngRepresentation.write(to: URL(fileURLWithPath: outDir + "/profile.png"))
    }

    func testUnfollow() throws {
        let app = XCUIApplication(bundleIdentifier: "xyz.blueskyweb.app")
        app.activate()
        sleep(2)
        let author = app.staticTexts["whiskers"].firstMatch
        XCTAssertTrue(author.waitForExistence(timeout: 15), "author label not found")
        author.tap()
        sleep(3)
        let button = app.buttons["Following"].firstMatch
        XCTAssertTrue(button.waitForExistence(timeout: 10), "Following button not found")
        button.tap()
        sleep(2)
        try? app.debugDescription.write(toFile: outDir + "/tree_after.txt", atomically: true, encoding: .utf8)
        let shot = XCUIScreen.main.screenshot()
        try? shot.pngRepresentation.write(to: URL(fileURLWithPath: outDir + "/after.png"))
    }
}

